// src/storage.ts
var DatabaseStorage = class {
  async getProxies() {
    return await db.select().from(proxies);
  }
  async createProxy(proxy) {
    const [created] = await db.insert(proxies).values(proxy).returning();
    return created;
  }
  async deleteProxy(id) {
    await db.delete(proxies).where(eq(proxies.id, id));
  }
  async getProfiles() {
    return await db.select().from(profiles);
  }
  async getProfile(id) {
    const [profile] = await db.select().from(profiles).where(eq(profiles.id, id));
    return profile;
  }
  async createProfile(profile) {
    const randomUA = userAgents[Math.floor(Math.random() * userAgents.length)];
    const [created] = await db.insert(profiles).values({
      ...profile,
      userAgentApi: randomUA.api,
      userAgentEmbedded: randomUA.embedded
    }).returning();
    await this.initializeToolsForProfile(created.id);
    return created;
  }
  async updateProfile(id, updates) {
    const [updated] = await db.update(profiles).set(updates).where(eq(profiles.id, id)).returning();
    return updated;
  }
  async deleteProfile(id) {
    await db.delete(tools).where(eq(tools.profileId, id));
    await db.delete(profiles).where(eq(profiles.id, id));
  }
  async updateProfileStatus(id, status) {
    const [updated] = await db.update(profiles).set({ status }).where(eq(profiles.id, id)).returning();
    return updated;
  }
  async getToolsByProfile(profileId) {
    const existing = await db.select().from(tools).where(eq(tools.profileId, profileId));
    const allTypes = ["follow", "unfollow", "like", "dm", "contact"];
    const existingTypes = new Set(existing.map((t2) => t2.type));
    const missing = allTypes.filter((t2) => !existingTypes.has(t2));
    if (missing.length > 0) {
      for (const type of missing) {
        await db.insert(tools).values({ profileId, type, enabled: false, settings: {} });
      }
      return await db.select().from(tools).where(eq(tools.profileId, profileId));
    }
    return existing;
  }
  async updateTool(id, updates) {
    const [updated] = await db.update(tools).set(updates).where(eq(tools.id, id)).returning();
    return updated;
  }
  async initializeToolsForProfile(profileId) {
    const toolTypes = ["follow", "unfollow", "like", "dm", "contact"];
    for (const type of toolTypes) {
      await db.insert(tools).values({ profileId, type, enabled: false, settings: {} });
    }
  }
  async getSourcesByTool(toolId) {
    return await db.select().from(sources).where(eq(sources.toolId, toolId));
  }
  async createSource(source) {
    const [created] = await db.insert(sources).values(source).returning();
    return created;
  }
  async deleteSource(id) {
    await db.delete(sources).where(eq(sources.id, id));
  }
  async getStatsByProfile(profileId) {
    return await db.select().from(stats).where(eq(stats.profileId, profileId));
  }
  async getInstagramApiCalls(limit = 1e5) {
    return await db.select().from(instagramApiCalls).orderBy(desc(instagramApiCalls.id)).limit(limit);
  }
  async createInstagramApiCall(call) {
    const [created] = await db.insert(instagramApiCalls).values({
      profileId: call.profileId,
      operationName: call.operationName,
      date: call.date,
      message: call.message ?? "",
      source: call.source ?? "",
      navChain: call.navChain ?? "",
      ipAddress: call.ipAddress ?? "",
      durationMs: call.durationMs ?? 0
    }).returning();
    return created;
  }
  async incrementStat(profileId, toolType) {
    const today = (/* @__PURE__ */ new Date()).toISOString().split("T")[0];
    const [daily] = await db.select().from(stats).where(and(eq(stats.profileId, profileId), eq(stats.toolType, toolType), eq(stats.date, today)));
    if (daily) {
      await db.update(stats).set({ count: daily.count + 1 }).where(eq(stats.id, daily.id));
    } else {
      await db.insert(stats).values({ profileId, toolType, count: 1, date: today });
    }
    const [lifetime] = await db.select().from(stats).where(and(eq(stats.profileId, profileId), eq(stats.toolType, toolType), eq(stats.date, "lifetime")));
    if (lifetime) {
      await db.update(stats).set({ count: lifetime.count + 1 }).where(eq(stats.id, lifetime.id));
    } else {
      await db.insert(stats).values({ profileId, toolType, count: 1, date: "lifetime" });
    }
  }
  async getFollowedUsersByProfile(profileId, limit = 1e4) {
    return await db.select().from(followedUsers).where(eq(followedUsers.profileId, profileId)).orderBy(desc(followedUsers.id)).limit(limit);
  }
  async createFollowedUser(entry) {
    const [created] = await db.insert(followedUsers).values(entry).returning();
    return created;
  }
  async deleteFollowedUser(id) {
    await db.delete(followedUsers).where(eq(followedUsers.id, id));
  }
  async countFollowsToday(profileId, todayPrefix) {
    const rows = await db.select({ count: sql`count(*)` }).from(followedUsers).where(and(
      eq(followedUsers.profileId, profileId),
      like(followedUsers.followedAt, `${todayPrefix}%`)
    ));
    return Number(rows[0]?.count ?? 0);
  }
  async countFollowsThisHour(profileId, hourPrefix) {
    const rows = await db.select({ count: sql`count(*)` }).from(followedUsers).where(and(
      eq(followedUsers.profileId, profileId),
      like(followedUsers.followedAt, `${hourPrefix}%`)
    ));
    return rows[0]?.count ?? 0;
  }
  async getSessionActionsByProfile(profileId, limit = 500) {
    return await db.select().from(sessionActions).where(eq(sessionActions.profileId, profileId)).orderBy(desc(sessionActions.id)).limit(limit);
  }
  async createSessionAction(entry) {
    const [created] = await db.insert(sessionActions).values(entry).returning();
    return created;
  }
  async getGlobalSettings() {
    const rows = await db.select().from(globalSettings);
    const out = {};
    for (const row of rows) out[row.key] = row.value;
    return out;
  }
  async setGlobalSetting(key, value) {
    await db.insert(globalSettings).values({ key, value }).onConflictDoUpdate({ target: globalSettings.key, set: { value } });
  }
  async isGloballySkipped(username) {
    const rows = await db.select({ id: skippedUsers.id }).from(skippedUsers).where(sql`LOWER(${skippedUsers.instagramUsername}) = LOWER(${username})`).limit(1);
    return rows.length > 0;
  }
  async isGloballyFollowed(username) {
    const rows = await db.select({ id: followedUsers.id }).from(followedUsers).where(sql`LOWER(${followedUsers.instagramUsername}) = LOWER(${username})`).limit(1);
    return rows.length > 0;
  }
  async addSkippedUser(username, reason) {
    await db.insert(skippedUsers).values({ instagramUsername: username, reason, skippedAt: (/* @__PURE__ */ new Date()).toISOString() }).onConflictDoNothing();
  }
  async getSkippedUsers(limit = 1e4) {
    return await db.select().from(skippedUsers).orderBy(desc(skippedUsers.id)).limit(limit);
  }
  async getRepostedPostsByProfile(profileId, limit = 500) {
    return await db.select().from(repostedPosts).where(eq(repostedPosts.profileId, profileId)).orderBy(desc(repostedPosts.id)).limit(limit);
  }
  async createRepostedPost(entry) {
    const [created] = await db.insert(repostedPosts).values(entry).returning();
    return created;
  }
  async deleteRepostedPost(id) {
    await db.delete(repostedPosts).where(eq(repostedPosts.id, id));
  }
  async isAlreadyReposted(profileId, mediaId) {
    const rows = await db.select({ id: repostedPosts.id }).from(repostedPosts).where(and(eq(repostedPosts.profileId, profileId), eq(repostedPosts.mediaId, mediaId))).limit(1);
    return rows.length > 0;
  }
  async getContactDmSentByProfile(profileId, limit = 1e3) {
    return await db.select().from(contactDmSent).where(eq(contactDmSent.profileId, profileId)).orderBy(desc(contactDmSent.id)).limit(limit);
  }
  async createContactDmSent(entry) {
    const [created] = await db.insert(contactDmSent).values(entry).returning();
    return created;
  }
  async isContactDmAlreadySent(profileId, instagramUsername) {
    const rows = await db.select({ id: contactDmSent.id }).from(contactDmSent).where(and(
      eq(contactDmSent.profileId, profileId),
      sql`LOWER(${contactDmSent.instagramUsername}) = LOWER(${instagramUsername})`
    )).limit(1);
    return rows.length > 0;
  }
  async deleteContactDmSent(id) {
    await db.delete(contactDmSent).where(eq(contactDmSent.id, id));
  }
  async getContactPendingMessages(profileId, status) {
    const conditions = status ? and(eq(contactPendingMessages.profileId, profileId), eq(contactPendingMessages.status, status)) : eq(contactPendingMessages.profileId, profileId);
    return await db.select().from(contactPendingMessages).where(conditions).orderBy(desc(contactPendingMessages.id));
  }
  async createContactPendingMessage(entry) {
    const [created] = await db.insert(contactPendingMessages).values(entry).returning();
    return created;
  }
  async updateContactPendingMessage(id, updates) {
    await db.update(contactPendingMessages).set(updates).where(eq(contactPendingMessages.id, id));
  }
  async deleteContactPendingMessage(id) {
    await db.delete(contactPendingMessages).where(eq(contactPendingMessages.id, id));
  }
  async isContactAlreadyQueued(profileId, instagramUsername) {
    const rows = await db.select({ id: contactPendingMessages.id }).from(contactPendingMessages).where(and(
      eq(contactPendingMessages.profileId, profileId),
      sql`LOWER(${contactPendingMessages.instagramUsername}) = LOWER(${instagramUsername})`
    )).limit(1);
    return rows.length > 0;
  }
  async isAutoReplyAlreadyQueued(profileId, instagramUsername) {
    const rows = await db.select({ id: contactPendingMessages.id }).from(contactPendingMessages).where(and(
      eq(contactPendingMessages.profileId, profileId),
      eq(contactPendingMessages.messageType, "auto_reply"),
      sql`LOWER(${contactPendingMessages.instagramUsername}) = LOWER(${instagramUsername})`
    )).limit(1);
    return rows.length > 0;
  }
  async getContactMessagesForUnsend(profileId) {
    const now = (/* @__PURE__ */ new Date()).toISOString();
    return await db.select().from(contactPendingMessages).where(and(
      eq(contactPendingMessages.profileId, profileId),
      eq(contactPendingMessages.status, "sent"),
      sql`${contactPendingMessages.unsendAt} IS NOT NULL AND ${contactPendingMessages.unsendAt} <= ${now}`
    ));
  }
};
var storage = new DatabaseStorage();

