var errorSchemas = {
  validation: external_exports.object({
    message: external_exports.string(),
    field: external_exports.string().optional()
  }),
  notFound: external_exports.object({
    message: external_exports.string()
  }),
  internal: external_exports.object({
    message: external_exports.string()
  })
};
